// --- creddb.Perm..ReadFieldMaybe
bool creddb::Perm_ReadFieldMaybe(creddb::Perm& parent, algo::strptr field, algo::strptr strval) {
    bool retval = true;
    creddb::FieldId field_id;
    (void)value_SetStrptrMaybe(field_id,field);
    switch(field_id) {
        case creddb_FieldId_perm: {
            retval = algo::Smallstr100_ReadStrptrMaybe(parent.perm, strval);
        } break;
        case creddb_FieldId_kind: {
            retval = false;
        } break;
        case creddb_FieldId_name: {
            retval = false;
        } break;
        case creddb_FieldId_comment: {
            retval = algo::Comment_ReadStrptrMaybe(parent.comment, strval);
        } break;
        default: {
            if (!ch_N(field) || (algo_lib::_db.strict_attr && field != "acr.rowid")) {
                retval = false;
                algo_lib::AppendErrtext("comment", "unrecognized attr");
            }
        } break;
    }
    if (!retval) {
        algo_lib::AppendErrtext("attr",field);
    }
    return retval;
}

// --- creddb.Perm..ReadStrptrMaybe
// Read fields of creddb::Perm from an ascii string.
// The format of the string is an ssim Tuple
bool creddb::Perm_ReadStrptrMaybe(creddb::Perm &parent, algo::strptr in_str) {
    bool retval = true;
    retval = algo::StripTypeTag(in_str, "creddb.perm") || algo::StripTypeTag(in_str, "creddb.Perm");
    ind_beg(algo::Attr_curs, attr, in_str) {
        retval = retval && Perm_ReadFieldMaybe(parent, attr.name, attr.value);
    }ind_end;
    return retval;
}

